sendEmail = async (to: string, subject: string, html: string, transportConfig?: EmailTransportConfig) => {
	let config: EmailTransportConfig;
	if (typeof transportConfig !== "undefined") {
		config = transportConfig;
	} else {
		config = await this.settingsService.getDBSettings();
	}

	// Validate required email configuration
	if (!config.systemEmailHost || !config.systemEmailPort || !config.systemEmailAddress || !config.systemEmailPassword) {
		this.logger.warn({
			message: "Email configuration incomplete - missing required fields (host, port, address, or password)",
			service: SERVICE_NAME,
			method: "sendEmail",
		});
		return false;
	}

	const {
		systemEmailHost,
		systemEmailPort,
		systemEmailSecure,
		systemEmailPool,
		systemEmailUser,
		systemEmailAddress,
		systemEmailPassword,
		systemEmailConnectionHost,
		systemEmailTLSServername,
		systemEmailIgnoreTLS,
		systemEmailRequireTLS,
		systemEmailRejectUnauthorized,
	} = config;

	const emailConfig = {
		host: systemEmailHost,
		port: Number(systemEmailPort),
		secure: systemEmailSecure,
		auth: {
			user: systemEmailUser || systemEmailAddress,
			pass: systemEmailPassword,
		},
		name: systemEmailConnectionHost || "localhost",
		connectionTimeout: 5000,
		pool: systemEmailPool,
		tls: {
			rejectUnauthorized: systemEmailRejectUnauthorized,
			ignoreTLS: systemEmailIgnoreTLS,
			requireTLS: systemEmailRequireTLS,
			servername: systemEmailTLSServername,
		},
	};
	this.transporter = this.nodemailer.createTransport(emailConfig);

	try {
		await this.transporter.verify();
	} catch (error: unknown) {
		const errorMessage = error instanceof Error ? error.message : "Unknown error";
		this.logger.error({
			message: `Email transporter verification failed: ${errorMessage}`,
			service: SERVICE_NAME,
			method: "verifyTransporter",
			stack: error instanceof Error ? error.stack : undefined,
			details: {
				host: systemEmailHost,
				port: systemEmailPort,
				secure: systemEmailSecure,
			},
		});
		return false;
	}

	try {
		const info = await this.transporter.sendMail({
			to: to,
			from: systemEmailAddress,
			subject: subject,
			html: html,
		});
		return info?.messageId;
	} catch (error: unknown) {
		const errorMessage = error instanceof Error ? error.message : "Unknown error";
		this.logger.error({
			message: `Failed to send email: ${errorMessage}`,
			service: SERVICE_NAME,
			method: "sendEmail",
			stack: error instanceof Error ? error.stack : undefined,
			details: {
				recipient: to,
				host: systemEmailHost,
				port: systemEmailPort,
			},
		});
	}
};

sendTestEmail = async (req: Request, res: Response, next: NextFunction) => {
	try {
		sendTestEmailBodyValidation.parse(req.body);

		const {
			to,
			systemEmailHost,
			systemEmailPort,
			systemEmailAddress,
			systemEmailPassword,
			systemEmailUser,
			systemEmailConnectionHost,
			systemEmailSecure,
			systemEmailPool,
			systemEmailIgnoreTLS,
			systemEmailRequireTLS,
			systemEmailRejectUnauthorized,
			systemEmailTLSServername,
		} = req.body;

		// Validate required fields
		if (!systemEmailHost || !systemEmailPort || !systemEmailAddress || !systemEmailPassword) {
			throw new AppError({
				message: "Email configuration incomplete. Please ensure Host, Port, Email Address, and Password are all provided.",
				status: 400,
			});
		}

		const subject = "This is a test email from Checkmate";
		const context = { testName: "Monitoring System" };

		const html = await this.emailService.buildEmail("testEmailTemplate", context);
		if (!html) {
			throw new AppError({ message: "Failed to build email template.", status: 500 });
		}
		const messageId = await this.emailService.sendEmail(to, subject, html, {
			systemEmailHost,
			systemEmailPort,
			systemEmailUser,
			systemEmailAddress,
			systemEmailPassword,
			systemEmailConnectionHost,
			systemEmailSecure,
			systemEmailPool,
			systemEmailIgnoreTLS,
			systemEmailRequireTLS,
			systemEmailRejectUnauthorized,
			systemEmailTLSServername,
		});

		if (!messageId) {
			throw new AppError({
				message: "Failed to send test email. Please check your email configuration credentials and server settings. If using Gmail, ensure you are using an App Password (not your regular password).",
				status: 500,
			});
		}

		return res.status(200).json({
			success: true,
			msg: "Test email sent successfully",
			data: { messageId },
		});
	} catch (error) {
		next(error);
	}
};

async sendTestAlert(notification: Partial<Notification>): Promise<boolean> {
	const subject = "Test notification";
	const html = await buildTestEmail(this.emailService);

	if (!notification.address) {
		this.logger.warn({
			message: "Missing address - cannot send test email",
			service: SERVICE_NAME,
			method: "sendTestAlert",
		});
		return false;
	}

	if (!html) {
		this.logger.warn({
			message: "Failed to build test email content",
			service: SERVICE_NAME,
			method: "sendTestAlert",
		});
		return false;
	}

	const messageId = await this.emailService.sendEmail(notification.address, subject, html);
	if (!messageId) {
		this.logger.error({
			message: "Email test alert failed - check email configuration (credentials, host, port)",
			service: SERVICE_NAME,
			method: "sendTestAlert",
		});
		return false;
	}
	return true;
}

async sendMessage(notification: Notification, message: NotificationMessage): Promise<boolean> {
	if (!notification.address) {
		this.logger.warn({
			message: "Missing email address for notification",
			service: SERVICE_NAME,
			method: "sendMessage",
		});
		return false;
	}

	const subject = this.buildSubject(message);
	const html = await this.buildEmailFromMessage(message);

	if (!html) {
		this.logger.warn({
			message: "Failed to build email content",
			service: SERVICE_NAME,
			method: "sendMessage",
		});
		return false;
	}

	const messageId = await this.emailService.sendEmail(notification.address, subject, html);
	if (!messageId) {
		this.logger.error({
			message: "Email notification failed - check email configuration (credentials, host, port)",
			service: SERVICE_NAME,
			method: "sendMessage",
			details: {
				monitorName: message.monitor.name,
				recipient: notification.address,
			},
		});
		return false;
	}
	return true;
}

